def write_report(libpcap, libyaml):
    import yaml

    with open(OUT_YAML, encoding="utf-8") as handle:
        raw = handle.read()

    parse_ok = True
    cfg = None
    try:
        cfg = yaml.safe_load(raw)
    except yaml.YAMLError as exc:
        parse_ok = False
        print("YAML parse error: %s" % exc)

    rule_files = []
    eve_enabled = False
    fast_enabled = False
    present_types = []
    if isinstance(cfg, dict):
        rule_files = cfg.get("rule-files") or []
        for output in cfg.get("outputs") or []:
            if not isinstance(output, dict):
                continue
            for name, body in output.items():
                if not isinstance(body, dict):
                    continue
                enabled = str(body.get("enabled", "yes")).lower() in ("yes", "true")
                if name == "eve-log":
                    eve_enabled = enabled
                    present_types = eve_types(body)
                elif name == "fast":
                    fast_enabled = enabled

    missing = [t for t in ("alert", "http", "tls", "stats") if t not in present_types]
    if missing:
        raise SystemExit("eve-log is missing required types: %s" % missing)

    report = {
        "placeholder_remaining": len(PLACEHOLDER_RE.findall(raw)),
        "rule_files_listed": len(rule_files),
